namespace NotificationsApp.Services;

/// <summary>
/// Periodically generates fake notifications so the polling page has new data to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.SimulateIncoming();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;
    private int _latestId;

    protected override void OnInitialized()
    {
        // During prerender this persists the data; during interactive init it restores it.
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (ApplicationState.TryTakeFromJson<List<NotificationsApp.Services.Notification>>(
                "notifications", out var restored))
        {
            // Interactive init: reuse data from prerender — no second service call.
            _notifications = restored!;
        }
        else
        {
            // Prerender (or no persisted state): load from the service.
            _notifications = NotificationSvc.GetAll();
        }

        _latestId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never runs during static SSR — only once the circuit is live.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = NotificationSvc.GetSince(_latestId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _latestId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

